<section class="hero"><p class="eyebrow"><?= $admin ? 'PANEL ADMINISTRATIVO' : 'PERIODISMO LOCAL · DEMOSTRACIÓN ACADÉMICA' ?></p><h1><?= $admin ? 'Gestionar noticias' : 'Noticias de Huancayo' ?></h1><p><?= $admin ? 'Organice, revise y publique las historias del blog.' : 'Comunidad, cultura y ciudad. Noticias ficticias para demostración académica.' ?></p><?php if ($admin): ?><a class="button" href="<?= e(url('news-edit')) ?>">Crear noticia</a><?php endif ?></section>
<form class="filters" method="get"><input type="hidden" name="r" value="<?= $admin ? 'news' : 'home' ?>"><div><label for="q">Buscar por título</label><input id="q" name="q" maxlength="160" value="<?= e($search) ?>" placeholder="¿Qué desea encontrar?"></div><div><label for="category">Categoría</label><select id="category" name="category"><option value="0">Todas las categorías</option><?php foreach ($categories as $c): ?><option value="<?= e($c['id']) ?>" <?= $category === (int)$c['id'] ? 'selected' : '' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></div><button>Buscar</button><a href="<?= e(url($admin ? 'news' : 'home')) ?>" class="button secondary">Limpiar filtros</a></form>
<p><?= e($listing['total']) ?> noticias encontradas</p><div class="grid"><?php foreach ($listing['rows'] as $n): ?><article class="card"><?php if ($n['image']): ?><img src="<?= e(($GLOBALS['config']['base_url'] ?? '') . '/uploads/' . $n['image']) ?>" alt="<?= e($n['image_alt']) ?>" loading="lazy" width="640" height="360"><?php endif ?><div class="card-body"><p class="eyebrow"><?= e($n['category']) ?> <?= $admin ? '· ' . ($n['status'] === 'draft' ? 'Borrador' : 'Publicado') : '' ?></p><h2><a href="<?= e(url($admin ? 'news-edit' : 'detail', ['id' => $n['id']])) ?>"><?= e($n['title']) ?></a></h2><p><?= e($n['summary']) ?></p><time datetime="<?= e($n['published_at'] ?? $n['created_at']) ?>"><?= e(substr($n['published_at'] ?? $n['created_at'], 0, 10)) ?></time><?php if ($admin): ?><div class="actions"><a href="<?= e(url('news-edit', ['id' => $n['id']])) ?>" aria-label="<?= e('Consultar y editar noticia: ' . $n['title']) ?>">Consultar y editar</a><a href="<?= e(url('news-delete', ['id' => $n['id']])) ?>" aria-label="<?= e('Revisar eliminación de noticia: ' . $n['title']) ?>">Revisar eliminación</a></div><?php endif ?></div></article><?php endforeach ?></div>
<?php if (!$listing['rows']): ?><p class="notice">No hay noticias para estos filtros. Pruebe otra búsqueda.</p><?php endif ?>
<nav class="pagination" aria-label="Paginación"><?php if ($listing['page'] > 1): ?><a href="<?= e(url($admin ? 'news' : 'home', ['q' => $search, 'category' => $category, 'page' => $listing['page'] - 1])) ?>">Anterior</a><?php endif ?><span aria-current="page">Página <?= e($listing['page']) ?> de <?= e($listing['pages']) ?></span><?php if ($listing['page'] < $listing['pages']): ?><a href="<?= e(url($admin ? 'news' : 'home', ['q' => $search, 'category' => $category, 'page' => $listing['page'] + 1])) ?>">Siguiente</a><?php endif ?></nav>
